(function(global){
 'use strict';
 const TABS=[['dashboard','看板'],['home','家园'],['collection','收集'],['nearby','附近'],['groups','小组'],['profile','我的']];
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function mount(target,config={}){
  const host=typeof target==='string'?document.querySelector(target):target;
  const state={hub:'mine',stack:[],modals:[]};
  host.innerHTML=`<div class=toolbox><div class=toolbox-top><header class=toolbox-header><h1>洛克工具箱</h1><div class=toolbox-header-actions><button type=button data-refresh>刷新</button><button type=button data-tutorial>教程</button></div></header><nav class=toolbox-nav aria-label=工具箱主导航>${TABS.map(([key,label])=>`<button type=button data-app-tab="${key}" ${key==='groups'?'aria-current=page':''}>${label}</button>`).join('')}</nav></div><div class=toolbox-root data-root><section class=toolbox-group><div class=toolbox-group-top><label class=toolbox-group-name><span class=toolbox-group-type>收集小组</span><select aria-label=当前小组 data-group-select><option>${esc(config.groupName||'收集小组')}</option></select></label><button type=button data-group-settings>设置</button><button type=button data-group-refresh>刷新</button></div><div class=toolbox-group-meta><span>${config.memberCount||6} 人</span><span>我的资源 · 已发布</span><button type=button data-resources>管理选号</button></div></section><div class=toolbox-hub-tabs role=group aria-label=计划中心><button type=button data-hub-tab=mine aria-pressed=true>我的收集</button><button type=button data-hub-tab=square aria-pressed=false>组内广场</button></div><div data-content></div></div><section class=toolbox-detail data-detail hidden aria-label=二级页面><header class=toolbox-detail-header><button type=button data-back aria-label=返回><svg viewBox="0 0 24 24" aria-hidden=true><path d="m14 6-6 6 6 6"/></svg></button><h2 data-detail-title></h2><span data-detail-context></span></header><div class=toolbox-detail-body data-detail-body></div></section><div class=toolbox-toast data-toast role=status></div></div>`;
  const q=s=>host.querySelector(s);
  const modalLayer=document.createElement('div');modalLayer.className='toolbox-modal-layer';modalLayer.hidden=true;modalLayer.innerHTML='<section class=toolbox-modal role=dialog aria-modal=true aria-labelledby=toolbox-modal-title tabindex=-1><header class=toolbox-modal-header><h2 id=toolbox-modal-title></h2><button type=button data-modal-close aria-label=关闭弹窗>×</button></header><div class=toolbox-modal-body></div></section>';q('.toolbox').append(modalLayer);
  function setBackgroundInert(value){q('.toolbox-top').inert=value;q('[data-root]').inert=value||!!state.stack.length;q('[data-detail]').inert=value||!state.stack.length;}
  function renderModal(item){modalLayer.hidden=false;setBackgroundInert(true);q('#toolbox-modal-title').textContent=item.title;q('.toolbox-modal-body').innerHTML=typeof item.render==='function'?item.render():item.html||'';q('.toolbox-modal-body').scrollTop=item.scroll||0;q('.toolbox-modal').focus({preventScroll:true});}
  function openModal(item){if(state.modals.length)state.modals.at(-1).scroll=q('.toolbox-modal-body').scrollTop;item.returnFocus=document.activeElement;state.modals.push(item);renderModal(item);}
  function closeModal(){const item=state.modals.pop();if(state.modals.length)renderModal(state.modals.at(-1));else{modalLayer.hidden=true;q('.toolbox-modal-body').replaceChildren();setBackgroundInert(false);if(item?.returnFocus?.isConnected)item.returnFocus.focus({preventScroll:true});}}
  function closeAllModals(){while(state.modals.length)closeModal();}
  modalLayer.addEventListener('click',event=>{if(event.target===modalLayer||event.target.closest('[data-modal-close]'))closeModal();});
  function toast(message){q('[data-toast]').textContent=message;q('[data-toast]').classList.add('on');global.clearTimeout(state.toastTimer);state.toastTimer=global.setTimeout(()=>q('[data-toast]').classList.remove('on'),1700)}
  function renderHub(){q('[data-content]').innerHTML=config.renderHub?config.renderHub(state.hub):'';q('[data-root]').hidden=false;q('[data-root]').inert=false;q('[data-detail]').hidden=true;host.querySelectorAll('[data-hub-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.hubTab===state.hub)));config.onRender?.({kind:'hub',hub:state.hub})}
  function selectHub(hub){if(!['mine','square'].includes(hub))return;closeAllModals();state.hub=hub;state.stack=[];renderHub()}
  function renderDetail(item){q('[data-root]').hidden=true;q('[data-root]').inert=true;q('[data-detail]').hidden=false;q('[data-detail-title]').textContent=item.title;q('[data-detail-context]').textContent=item.context||'';q('[data-detail-body]').innerHTML=typeof item.render==='function'?item.render():item.html||'';q('[data-detail-body]').scrollTop=item.scroll||0;config.onRender?.({kind:'detail',title:item.title});q('[data-detail-title]').setAttribute('tabindex','-1');q('[data-detail-title]').focus({preventScroll:true})}
  function openDetail(item){closeAllModals();if(state.stack.length)state.stack.at(-1).scroll=q('[data-detail-body]').scrollTop;else{state.rootScroll=q('[data-root]').scrollTop;state.returnFocus=document.activeElement;}state.stack.push(item);q('[data-detail]').inert=false;renderDetail(item)}
  function back(){state.stack.pop();if(state.stack.length)renderDetail(state.stack.at(-1));else{renderHub();q('[data-root]').scrollTop=state.rootScroll||0;const key=state.returnFocus?.dataset?.focusKey;const restored=key?host.querySelector('[data-focus-key="'+key+'"]'):null;restored?.focus({preventScroll:true})}}
  function refresh(){if(state.modals.length)renderModal(state.modals.at(-1));else if(state.stack.length)renderDetail(state.stack.at(-1));else renderHub()}
  host.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-hub-tab'))selectHub(b.dataset.hubTab);else if(b.hasAttribute('data-back'))back();else if(b.hasAttribute('data-app-tab')){if(b.dataset.appTab==='groups'){state.stack=[];renderHub()}else toast('本原型仅演示小组内换蛋')}else if(b.matches('[data-refresh],[data-group-refresh]')){refresh();toast('已刷新')}else if(b.hasAttribute('data-tutorial'))toast('教程沿用工具箱现有引导');else if(b.hasAttribute('data-group-settings'))openDetail({title:'小组设置',render:()=>'<div class=toolbox-panel><strong>'+esc(config.groupName||'收集小组')+'</strong><p class=toolbox-muted>成员与邀请 · 我的共享资源 · 切换小组</p></div>'});else if(b.hasAttribute('data-resources'))toast('沿用现有管理选号面板')});
  const keyHandler=e=>{if(e.key==='Escape'&&state.modals.length){e.preventDefault();closeModal();return;}if(e.key==='Tab'&&state.modals.length){const focusable=[...modalLayer.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')].filter(el=>!el.closest('[hidden]'));const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===q('.toolbox-modal'))){e.preventDefault();last?.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===q('.toolbox-modal'))){e.preventDefault();first?.focus();}return;}if(e.key==='Escape'&&state.stack.length){e.preventDefault();back()}};host.addEventListener('keydown',keyHandler);
  renderHub();return{state,selectHub,openDetail,back,refresh,toast,host,openModal,closeModal,closeAllModals};
 }
 global.ToolboxShell={mount,version:'2026-11-16',tabs:TABS};
})(window);
